        h = (h * 16777619) & 0xffffffff
    return h

id_to_word={0:"</s>",1:"joy",2:"sad",3:"horrible",4:"awful",5:"terrible",6:"bad",7:"hate",8:"love",9:"happy",10:"excellent",11:"wonderful",12:"great",13:"good",14:"anger",15:"mean",16:"nice",17:"is",18:"this"}
