best=0
bestpc=None
# brute force P1,P2 in 0..99, C from first equation
for P1 in range(100):
    for P2 in range(100):
        # C = b0 - f1*P1 - f2*P2 mod100
        f1=fnvs[pairs[0][0][0]]
