// FastText reimplementation from behavioral observation.
// Original behavior reverse-engineered via black-box testing.
#include <bits/stdc++.h>
using namespace std;

// Forward declarations
namespace myfasttext {
struct Args;
struct Dictionary;
struct DenseMatrix;
struct Model;
struct FastText;
}

using namespace myfasttext;

// ============ Utils ============
static inline vector<string> splitSpaces(const string& s) {
    vector<string> out;
    string cur;
    for (size_t i=0;i<s.size();i++) {
        char c=s[i];
        if (c==' '||c=='\t'||c=='\r'||c=='\n'||c=='\v'||c=='\f') {
            if (!cur.empty()) { out.push_back(cur); cur.clear(); }
        } else {
            cur.push_back(c);
        }
    }
    if (!cur.empty()) out.push_back(cur);
    return out;
}
static inline uint32_t fnv1a_hash(const string& s) {
    uint32_t h = 2166136261u;
    for (unsigned char c : s) {
        h ^= (uint32_t)c;
        h *= 16777619u;
    }
    return h;
}
static inline uint32_t fnv1a_hash_bytes(const char* data, size_t len) {
    uint32_t h = 2166136261u;
    for (size_t i=0;i<len;i++) {
        h ^= (uint32_t)(unsigned char)data[i];
        h *= 16777619u;
    }
    return h;
}

