// ============ Inference ============
static vector<pair<float,int>> predictLine(FastText& ft, const string& line, int k, float threshold) {
    // Returns top k (labelId, prob) with prob>=threshold, sorted descending prob
    // Hidden = sentence vector for sup? Actually for predict, hidden is same as getSentenceVector? For sup, getSentenceVector includes EOS and averages. Good. Use that.
    // But getSentenceVector for sup already handles labels filtering, OOV, EOS, etc. Good.
    // For predict, input line may contain labels? For test, line contains labels+text, but predict is for raw text (may contain labels? We filter labels as in getSentenceVector). Good.
    // Compute hidden
    vector<float> hidden = ft.getSentenceVector(line);
    int nlabels = ft.dict.nlabels;
    int dim = ft.args.dim;
    vector<pair<float,int>> all;
    if (nlabels==0) return all;
    if (dim==0) {
        // With dim 0, hidden zeros, logits zeros, probs uniform? Original with dim 0? What does predict give? Let's assume uniform (1/nlabels) for all? Or zeros? Need to test dim 0 predict. For now, return uniform.
        float p = 1.0f/nlabels;
        for (int i=0;i<nlabels;i++) all.push_back({p,i});
        // Sort? All equal, order? Possibly by label order? Original? Unknown. We'll sort by prob (all equal) then by label id? Stable? Use dict order (which is sorted by count). Good.
        // For k and threshold, filter.
        // Since all equal, top k are first k in dict order? Good.
    } else {
        vector<float> logits(nlabels,0.0f);
        for (int i=0;i<nlabels;i++) {
            const float* orow = ft.output_.row(i);
            float s=0;
            for (int d=0;d<dim;d++) s+=orow[d]*hidden[d];
            logits[i]=s;
        }
        // Softmax
        float mx=*max_element(logits.begin(), logits.end());
        vector<float> probs(nlabels);
        float sum=0;
        for (int i=0;i<nlabels;i++) { probs[i]=expf(logits[i]-mx); sum+=probs[i]; }
        for (int i=0;i<nlabels;i++) probs[i]/=sum;
        for (int i=0;i<nlabels;i++) all.push_back({probs[i],i});
    }
    sort(all.begin(), all.end(), [](auto &a, auto &b){
        if (fabs(a.first-b.first)>1e-9) return a.first>b.first;
        return a.second<b.second; // tie-break by label id (dict order)
    });
    if ((int)all.size()>k) all.resize(k);
    // Filter by threshold
    vector<pair<float,int>> filtered;
    for (auto &p: all) if (p.first>=threshold) filtered.push_back(p);
    return filtered;
}

