#include <bits/stdc++.h>
using namespace std;
uint32_t fnv1a_hash(const string& s) {
    uint32_t h=2166136261u;
    for (unsigned char c: s) { h^=c; h*=16777619u; }
    return h;
}
struct FNVHash {
    size_t operator()(const string& s) const { return fnv1a_hash(s); }
};
vector<string> splitSpaces(const string& s) {
    vector<string> out; string cur;
    for(char c:s){ if(c==' '||c=='\t'||c=='\r'||c=='\n'){ if(!cur.empty()){out.push_back(cur);cur.clear();} } else cur.push_back(c); }
    if(!cur.empty()) out.push_back(cur);
    return out;
}
int main() {
    // Build dict for train_huge with FNV hasher, pre-insert </s>?
    unordered_map<string,int64_t,FNVHash> wordCounts;
    unordered_map<string,int64_t> labelCounts; // use std for labels? Or FNV for both? Try FNV for both.
    // Actually use FNV for both to test
    unordered_map<string,int64_t,FNVHash> labelCountsFNV;
    wordCounts["</s>"]=0;
    ifstream in("/tmp/train_huge.txt");
    string line;
    while(getline(in,line)){
        auto toks=splitSpaces(line);
        for(auto &t: toks){
            if(t.rfind("__label__",0)==0) labelCountsFNV[t]++;
            else wordCounts[t]++;
        }
        wordCounts["</s>"]++;
    }
    struct E{string w; int64_t c;};
    vector<E> words;
    for(auto &p: wordCounts) if(p.second>=1) words.push_back({p.first,p.second});
